#include <bits/stdc++.h>
using namespace std;

int evaluate(vector<char>& s, char x) {
    for (int i = 0; i < s.size(); i++) {
        if (s[i] == 'X') s[i] = x;
    }
    if (s[0] == '0') return 0;
    int count = 1;
    bool firstXFlag = true;
    for (int i = 0; i < s.size(); i++) {
        if (s[i] == '_') {
            count *= (i == 0) ? 9 : 10;
        } else if (s[i] == 'X' && firstXFlag) {
            count *= (i == 0) ? 9 : 10;
            firstXFlag = false;
        }
    }
    return count;
}

bool isValidReplacement(const vector<char>& s, char a, char b) {
    int n = s.size();
    if (n >= 2) {
        if (s[n - 2] >= '0' && s[n - 2] <= '9' && s[n - 2] != a) return false;
        if (s[n - 1] >= '0' && s[n - 1] <= '9' && s[n - 1] != b) return false;
        if (s[n - 2] == 'X' && s[n - 1] == 'X' && a != b) return false;
    }
    return true;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    vector<char> s(line.begin(), line.end());
    int n = s.size();

    if (n < 2) {
        char c = s[0];
        if (c == '0' || c == '_' || c == 'X') {
            cout << 1 << "\n";
        } else {
            cout << 0 << "\n";
        }
        return 0;
    }

    int totalWays = 0;
    vector<pair<char, char>> replacements = {
        {'0', '0'},
        {'2', '5'},
        {'5', '0'},
        {'7', '5'}
    };

    for (auto& rep : replacements) {
        if (isValidReplacement(s, rep.first, rep.second)) {
            vector<char> t = s;
            t[n - 2] = rep.first;
            t[n - 1] = rep.second;
            if (s[n - 2] == 'X') {
                totalWays += evaluate(t, t[n - 2]);
            } else if (s[n - 1] == 'X') {
                totalWays += evaluate(t, t[n - 1]);
            } else {
                totalWays += evaluate(t, 'X');
            }
        }
    }

    cout << totalWays << "\n";

    return 0;
}

